function total() {
  return this.price * this.count;
}

const tea = { price: 3, count: 2 };
const cake = { price: 5, count: 4, total: total.bind(tea) };
const again = cake.total.bind(cake);

console.log(cake.total());
console.log(total.call(cake));
console.log(again());
console.log(cake.total.call(cake));
